CREATE COLUMN TABLE "TEST_AP"."OACK" ("AbsId" INTEGER CS_INT NOT NULL , "FinYear" INTEGER CS_INT NOT NULL , "Quarter" NVARCHAR(1) NOT NULL , "AckNum" NVARCHAR(100), "Location" INTEGER CS_INT NOT NULL , PRIMARY KEY ("AbsId")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OACK_LOC_QUART" ON "TEST_AP"."OACK" ( "FinYear" ASC, "Quarter" ASC, "Location" ASC )